-- Migration 043: Catálogo de tipos de projeto (Feature #65, parte 1) +
-- fingerprint de spec para REUSO SILENCIOSO (Feature #65, parte 2).
--
-- NOTA IMPORTANTE sobre o formato: o runner de migrations (db/init.ts) faz split
-- ingênuo por ';' e remove linhas que começam com '--'. Por isso, nenhum literal de
-- string abaixo contém ';' nem aspas simples, e os templates usam strings de escape
-- E'...' com \n (uma linha física por template) em vez de quebras reais.
--
-- ── Parte 2: fingerprint (reuso silencioso, intra-tenant) ──────────────────────
-- spec_fingerprint = SHA-256 do conteúdo NORMALIZADO das specs (ver
-- projectCreation.ts::computeSpecFingerprint). Usado para detectar, no momento da
-- criação, um projeto anterior do MESMO tenant com a mesma spec, e reaproveitar
-- artefatos/estrutura. NUNCA cruza tenants. NULL para projetos legados.
ALTER TABLE projects ADD COLUMN IF NOT EXISTS spec_fingerprint TEXT;

CREATE INDEX IF NOT EXISTS idx_projects_tenant_fingerprint
  ON projects (tenant_id, spec_fingerprint)
  WHERE spec_fingerprint IS NOT NULL;

-- ── Parte 1: catálogo de SPECs pré-prontas categorizadas ───────────────────────
-- Este é um STARTER SET honesto e extensível (dezenas de tipos cobrindo categorias
-- BR e do mundo). A infraestrutura (tabela + rotas GET /api/catalog e
-- POST /api/catalog/:slug/use) suporta crescer para a ordem de ~1000 tipos sem
-- mudança de schema: basta inserir novas linhas aqui (ou por seed adicional).
CREATE TABLE IF NOT EXISTS spec_catalog (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  slug              TEXT NOT NULL UNIQUE,
  title             TEXT NOT NULL,
  category          TEXT NOT NULL,
  description       TEXT NOT NULL DEFAULT '',
  template_markdown TEXT NOT NULL,
  tags              TEXT[] NOT NULL DEFAULT '{}',
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_spec_catalog_category ON spec_catalog(category);

ON CONFLICT (slug) DO NOTHING;
